using System;
using System.IO;
using System.Text;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Web.Script.Serialization;
class ManagedCrashObserver {
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetProcessTimes(IntPtr h,out long creation,out long exit,out long kernel,out long user);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool TerminateProcess(IntPtr h,uint code);
 const uint CrashCode=73;
 static string Quote(string v){var b=new StringBuilder("\"");int n=0;foreach(char c in v){if(c=='\\'){n++;continue;}if(c=='"')b.Append('\\',n*2+1);else b.Append('\\',n);b.Append(c);n=0;}return b.Append('\\',n*2).Append('"').ToString();}
 static void Check(bool b){if(!b)throw new InvalidOperationException("fixed fixture assertion");}
 static string Hash(string p){using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static Process Start(string exe,string mode,string root){var p=new Process();p.StartInfo=new ProcessStartInfo(exe,Quote(mode)+" "+Quote(root)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};Check(p.Start());return p;}
 static string ReadBound(StreamReader r){var b=new StringBuilder();char[] c=new char[128];int n;while((n=r.Read(c,0,c.Length))!=0){Check(b.Length+n<=4096);b.Append(c,0,n);}return b.ToString();}
 static string ReadReady(StreamReader r){var b=new StringBuilder();int c;while((c=r.Read())!=-1){if(c==10)return b.ToString().TrimEnd('\r');Check(b.Length<4096);b.Append((char)c);}throw new InvalidOperationException("ready EOF");}
 static void Stop(Process p){if(p==null)return;try{if(!p.HasExited){Check(TerminateProcess(p.Handle,74));Check(p.WaitForExit(5000));}}finally{p.Dispose();}}
 static void Command(string exe,string mode,string root,string status){Process p=null;try{p=Start(exe,mode,root);var o=Task.Factory.StartNew(()=>ReadBound(p.StandardOutput));var e=Task.Factory.StartNew(()=>ReadBound(p.StandardError));Check(p.WaitForExit(10000));Check(Task.WaitAll(new Task[]{o,e},5000));Check(p.ExitCode==0&&o.Result.Trim()=="{\"status\":\""+status+"\"}"&&e.Result.Length==0);}finally{Stop(p);}}
 static object Case(string exe,string mode,string output){string root=Path.Combine(output,"owned-"+mode);Directory.CreateDirectory(root);string sentinel=Path.Combine(root,"foreign-sentinel");File.WriteAllText(sentinel,"synthetic foreign preserve");Command(exe,"setup",root,"setup");string source=Path.Combine(root,"source"),payload=Path.Combine(root,"managed","fixture","1","synthetic","tool");string sh=Hash(source),ph=Hash(payload),fh=Hash(sentinel);Process child=null;try{child=Start(exe,"hold",root);IntPtr original=child.Handle;long creation,exit,kernel,user;Check(GetProcessTimes(original,out creation,out exit,out kernel,out user)&&creation!=0);var ready=Task.Factory.StartNew(()=>ReadReady(child.StandardOutput));Check(ready.Wait(10000)&&ready.Result=="{\"status\":\"ready\"}");var o=Task.Factory.StartNew(()=>ReadBound(child.StandardOutput));var e=Task.Factory.StartNew(()=>ReadBound(child.StandardError));if(mode=="crash")Check(TerminateProcess(original,CrashCode));else{child.StandardInput.Write("F");child.StandardInput.Flush();child.StandardInput.Close();}Check(child.WaitForExit(10000));Check(Task.WaitAll(new Task[]{o,e},5000));Check(child.ExitCode==(mode=="crash"?(int)CrashCode:0));Check(e.Result.Length==0);string expected=mode=="crash"?"pending":"clear";Command(exe,"probe-"+expected,root,expected);Check(Hash(source)==sh&&Hash(payload)==ph&&Hash(sentinel)==fh);string pending=Path.Combine(root,"managed",".execution-pending");Check(File.Exists(pending)==(mode=="crash"));return new{mode=mode,status="PASS",original_pid=child.Id,creation_filetime=creation,exit_code=child.ExitCode,mutation=expected,source_sha256=sh,payload_sha256_before=ph,payload_sha256_after=Hash(payload),sentinel_sha256=fh,pending_bytes=File.Exists(pending)?new FileInfo(pending).Length:0};}finally{Stop(child);}}
 static int Main(string[] a){try{Check(a.Length==2&&Path.IsPathRooted(a[0])&&Path.IsPathRooted(a[1]));string before=Hash(a[0]);var cases=new object[]{Case(a[0],"normal",a[1]),Case(a[0],"crash",a[1])};Check(Hash(a[0])==before);string json=new JavaScriptSerializer().Serialize(new{status="PASS",scope="Windows original process termination; no guardian handoff or automatic recovery",fixture_sha256=before,cases=cases});File.WriteAllText(Path.Combine(a[1],"native-result.json"),json+"\n");Console.WriteLine(json);return 0;}catch(Exception e){Console.Error.WriteLine("managed crash probe failed: "+e.GetType().Name);return 2;}}
}
